mapper.update:
update pubcar_car_insurance t set t.b_id = #{newInsuranceBId}

    , t.quarter_review= #{quarterReview}


    , t.quarter_review_content= #{quarterReviewContent}


    , t.year_review= #{yearReview}


    , t.year_review_content= #{yearReviewContent}


    , t.insurance_expiration_date= #{insuranceExpirationDate}


    , t.maintenance_expiration_date= #{maintenanceExpirationDate}


    , t.insurance_company= #{insuranceCompany}


    , t.maintenance_fee= #{maintenanceFee}


    , t.mileage= #{mileage}



        t.insurance_id= #{insuranceId}


        and t.b_id= #{bId}
